<?php require_once 'config/auth.php'; require_login(); $pageTitle='Registrar movimiento'; $tipo=$_GET['tipo']??'entrada'; if(!in_array($tipo,['entrada','salida'],true))$tipo='entrada';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $tipoPost=$_POST['tipo']??'entrada'; $id=(int)($_POST['producto']??0);$cantidad=(int)($_POST['cantidad']??0);$obs=trim($_POST['observacion']??'');
 if(!in_array($tipoPost,['entrada','salida'],true)||$cantidad<=0){flash('danger','Verifica el tipo y la cantidad del movimiento.'); redirect('movimiento.php?tipo='.urlencode($tipoPost));}
 try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT id_producto,nombre,stock_actual FROM producto WHERE id_producto=? AND estado=1 FOR UPDATE');$st->execute([$id]);$p=$st->fetch();if(!$p)throw new RuntimeException('El producto seleccionado no existe.');if($tipoPost==='salida'&&$cantidad>(int)$p['stock_actual'])throw new RuntimeException('La salida supera el stock disponible.');$delta=$tipoPost==='entrada'?$cantidad:-$cantidad;$pdo->prepare('UPDATE producto SET stock_actual=stock_actual+? WHERE id_producto=?')->execute([$delta,$id]);$pdo->prepare('INSERT INTO movimiento(id_producto,id_usuario,tipo,cantidad,observacion) VALUES(?,?,?,?,?)')->execute([$id,$_SESSION['user']['id_usuario'],$tipoPost,$cantidad,$obs]);$pdo->commit();flash('success','Movimiento registrado correctamente.');redirect('movimiento.php?tipo='.$tipoPost);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger',$e->getMessage());redirect('movimiento.php?tipo='.$tipoPost);}}
$products=$pdo->query('SELECT id_producto,nombre,codigo,stock_actual FROM producto WHERE estado=1 ORDER BY nombre')->fetchAll(); require 'partials/header.php'; ?>
<div class="page-head"><div><span class="eyebrow">INVENTARIO</span><h1>Registrar <?=e($tipo)?></h1><p>Los movimientos actualizan el stock de forma transaccional.</p></div><div class="tabs"><a class="<?= $tipo==='entrada'?'active':''?>" href="movimiento.php?tipo=entrada">Entrada</a><a class="<?= $tipo==='salida'?'active':''?>" href="movimiento.php?tipo=salida">Salida</a></div></div>
<div class="form-panel"><form method="post" class="form" data-movement-form><input type="hidden" name="tipo" value="<?=e($tipo)?>"><label>Producto<select name="producto" required data-stock-select><?php if(!$products): ?><option value="" disabled selected>No hay productos activos</option><?php endif; ?><?php foreach($products as $p):?><option value="<?=$p['id_producto']?>" data-stock="<?=$p['stock_actual']?>"><?=e($p['nombre'])?> · <?=e($p['codigo'])?> · stock <?=e((string)$p['stock_actual'])?></option><?php endforeach;?></select></label><label>Cantidad<input type="number" name="cantidad" min="1" required data-qty></label><div class="stock-help" data-stock-help></div><label>Observación <span class="muted">(opcional)</span><textarea name="observacion" maxlength="255" placeholder="Ej. Compra al proveedor, ajuste de inventario..."></textarea></label><button class="btn primary" type="submit" <?= !$products ? "disabled" : "" ?>>Guardar <?=e($tipo)?></button></form></div>
<?php require 'partials/footer.php'; ?>
